def main():
    for fn, anchor, new_paras in ADD:
        path = BASE + fn
        lines = io.open(path, encoding="utf-8").read().split("\n")
        if new_paras[0][:45] in "\n".join(lines):
            print("ALREADY:", fn, anchor[:40])
            continue
        idx = [i for i, l in enumerate(lines) if anchor in l]
        if len(idx) != 1:
            print("SKIP (%d matches):" % len(idx), fn, anchor[:60])
            continue
        i = idx[0]
        # конец текущего абзаца
        end = i
        while end + 1 < len(lines) and lines[end + 1].strip() and not lines[end + 1].startswith("#") and not lines[end + 1].startswith("|"):
            end += 1
        ins = [""] + list(new_paras)
        lines[end + 1:end + 1] = ins
        io.open(path, "w", encoding="utf-8").write("\n".join(lines))
    print("done")


main()
